# Alpine mkimage profile for the pcDuino Lite (Allwinner A10) audio appliance.
# Loaded by aports/scripts/mkimage.sh from ~/.mkimage, where
# scripts/build-image.sh copies it together with board.conf, appliance.conf,
# packages.list and the apkovl generator. The output tarball is unpacked onto
# the SD card's FAT partition; U-Boot is written raw by
# boards/pcduino/write-sdcard.sh (u-boot-sunxi-with-spl.bin at 8 KiB).

pcduino_extlinux_gen() {
	cat <<-EOF
	# Generated by mkimg.pcduino.sh
	DEFAULT $KERNEL_FLAVOR
	TIMEOUT 10
	LABEL $KERNEL_FLAVOR
	MENU LABEL Alpine Linux ($KERNEL_FLAVOR)
	KERNEL /boot/vmlinuz-$KERNEL_FLAVOR
	INITRD /boot/initramfs-$KERNEL_FLAVOR
	FDT /boot/dtbs-$KERNEL_FLAVOR/$DTB
	APPEND $initfs_cmdline $kernel_cmdline
	EOF
}

build_pcduino_extlinux() {
	mkdir -p "$DESTDIR"/extlinux
	pcduino_extlinux_gen > "$DESTDIR"/extlinux/extlinux.conf
}

section_pcduino_extlinux() {
	[ -n "$pcduino_extlinux" ] || return 0
	build_section pcduino_extlinux $(pcduino_extlinux_gen | checksum)
}

profile_pcduino() {
	profile_base
	. "$HOME"/.mkimage/board.conf
	. "$HOME"/.mkimage/appliance.conf
	title="$BOARD_NAME"
	desc="Diskless Alpine for the $BOARD_NAME audio appliance."
	image_ext="tar.gz"
	arch="$ALPINE_ARCH"
	kernel_flavors="$KERNEL_FLAVOR"
	kernel_addons=
	initfs_features="base mmc squashfs usb"
	# No "quiet": the boot log on serial is the main debugging tool.
	initfs_cmdline="modules=loop,squashfs,sd-mod,usb-storage"
	# HDMI (tty0) as well as serial, and last, so OpenRC's output goes there too
	# (the last console= is /dev/console): the pcDuino is brought up without a
	# serial adapter. consoleblank=0: the last messages stay on screen.
	kernel_cmdline="console=$CONSOLE console=tty0 consoleblank=0"
	modloopfw="$MODLOOP_EXTRA_FIRMWARE"
	pcduino_extlinux=yes
	# U-Boot + extlinux boot; no GRUB/EFI (profile_base enables it for ARM).
	grub_mod=
	# The appliance (panda-appliance depends on packages.list) and its board.
	apks="$(sed 's/#.*//' "$HOME"/.mkimage/packages.list) $BOARD_PACKAGES panda-appliance panda-board-$BOARD"
	apkovl="genapkovl.sh"
	hostname="$HOSTNAME"
}
